import type { ComponentInstance } from '@primereact/types/core';
import type { BaseComponentProps, PassThroughType } from '../..';
import type { DataViewRootInstance } from './DataViewRoot.types';
/**
 * Defines passthrough(pt) options type in DataViewContent component.
 */
export type DataViewContentPassThroughType<E> = PassThroughType<DataViewContentInstance, E>;
/**
 * Defines passthrough(pt) options of DataViewContent component.
 */
export interface DataViewContentPassThrough {
    /**
     * Used to pass attributes to the root's DOM element.
     */
    root?: DataViewContentPassThroughType<React.HTMLAttributes<HTMLDivElement>>;
}
/**
 * Defines valid properties in DataViewContent component.
 */
export interface DataViewContentProps extends BaseComponentProps<DataViewContentInstance, unknown, DataViewContentPassThrough, 'div'> {
}
/**
 * Defines valid state in DataViewContent component.
 */
export interface DataViewContentState {
}
/**
 * Defines the methods and properties exposed by DataViewContent component.
 */
export interface DataViewContentExposes {
    /**
     * The DataView component instance.
     */
    dataview: DataViewRootInstance | undefined | null;
}
/**
 * Instance of DataViewContent component.
 */
export type DataViewContentInstance = ComponentInstance<DataViewContentProps, DataViewContentState, DataViewContentExposes>;
